CREATE TABLE public.profiles (id UUID NOT NULL PRIMARY KEY,handle TEXT NOT NULL UNIQUE,display_name TEXT,bio TEXT,avatar_url TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "profiles_public_read" ON public.profiles FOR SELECT USING (true); CREATE POLICY "profiles_insert_own" ON public.profiles FOR INSERT TO authenticated WITH CHECK(auth.uid()=id); CREATE POLICY "profiles_update_own" ON public.profiles FOR UPDATE TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
CREATE TABLE public.posts(id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,author_id UUID NOT NULL,kind TEXT NOT NULL CHECK(kind IN('callout','thesis','meta','watch')),mint TEXT,symbol TEXT,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',entry_price NUMERIC,entry_market_cap NUMERIC,narrative TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX posts_created_at_idx ON public.posts(created_at DESC); CREATE INDEX posts_kind_idx ON public.posts(kind); CREATE INDEX posts_mint_idx ON public.posts(mint); GRANT SELECT ON public.posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.posts TO authenticated; ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY; CREATE POLICY "posts_public_read" ON public.posts FOR SELECT USING(true); CREATE POLICY "posts_insert_own" ON public.posts FOR INSERT TO authenticated WITH CHECK(auth.uid()=author_id); CREATE POLICY "posts_update_own" ON public.posts FOR UPDATE TO authenticated USING(auth.uid()=author_id) WITH CHECK(auth.uid()=author_id); CREATE POLICY "posts_delete_own" ON public.posts FOR DELETE TO authenticated USING(auth.uid()=author_id);
CREATE TABLE public.comments(id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,post_id UUID NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,author_id UUID NOT NULL,body TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT ON public.comments TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.comments TO authenticated; ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY; CREATE POLICY "comments_public_read" ON public.comments FOR SELECT USING(true); CREATE POLICY "comments_insert_own" ON public.comments FOR INSERT TO authenticated WITH CHECK(auth.uid()=author_id); CREATE POLICY "comments_delete_own" ON public.comments FOR DELETE TO authenticated USING(auth.uid()=author_id);
CREATE TABLE public.reactions(post_id UUID NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,user_id UUID NOT NULL,emoji TEXT NOT NULL DEFAULT '🔥',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(post_id,user_id)); GRANT SELECT ON public.reactions TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.reactions TO authenticated; ALTER TABLE public.reactions ENABLE ROW LEVEL SECURITY; CREATE POLICY "reactions_public_read" ON public.reactions FOR SELECT USING(true); CREATE POLICY "reactions_manage_own" ON public.reactions FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.bookmarks(post_id UUID NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,user_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(post_id,user_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.bookmarks TO authenticated; ALTER TABLE public.bookmarks ENABLE ROW LEVEL SECURITY; CREATE POLICY "bookmarks_manage_own" ON public.bookmarks FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.watchlist(id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,user_id UUID NOT NULL,mint TEXT NOT NULL,symbol TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,mint)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.watchlist TO authenticated; ALTER TABLE public.watchlist ENABLE ROW LEVEL SECURITY; CREATE POLICY "watchlist_manage_own" ON public.watchlist FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.follows(follower_id UUID NOT NULL,following_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(follower_id,following_id)); GRANT SELECT ON public.follows TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.follows TO authenticated; ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY; CREATE POLICY "follows_public_read" ON public.follows FOR SELECT USING(true); CREATE POLICY "follows_manage_own" ON public.follows FOR ALL TO authenticated USING(auth.uid()=follower_id) WITH CHECK(auth.uid()=follower_id);
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE base TEXT; candidate TEXT; suffix INT:=0; BEGIN base:=lower(regexp_replace(split_part(coalesce(NEW.email,'trader'),'@',1),'[^a-z0-9_]','','g')); IF base='' THEN base:='trader'; END IF; candidate:=base; WHILE EXISTS(SELECT 1 FROM public.profiles WHERE handle=candidate) LOOP suffix:=suffix+1; candidate:=base||suffix::text; END LOOP; INSERT INTO public.profiles(id,handle,display_name) VALUES(NEW.id,candidate,candidate) ON CONFLICT(id) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user(); ALTER PUBLICATION supabase_realtime ADD TABLE public.posts; ALTER PUBLICATION supabase_realtime ADD TABLE public.comments; ALTER PUBLICATION supabase_realtime ADD TABLE public.reactions;
